#!/data/data/com.termux/files/usr/bin/bash
# freebuff launcher — generated by freebuff-native install.sh.
# Runs the official npm launcher with the environment this device needs:
# local CONNECT proxy, release target override, patched binary upkeep.
set -eu
DIR="@NATIVE_DIR@"
PREFIX="${FREEBUFF_PREFIX:-@PREFIX@}"
CONF="$HOME/.config/manicode"
BIN="$CONF/freebuff"
BAK="$DIR/bak"
MD5F="$DIR/freebuff.md5"
LAUNCHER="$PREFIX/lib/node_modules/freebuff/index.js"
PORT="${FREEBUFF_PROXY_PORT:-8975}"
export TMPDIR="${TMPDIR:-$PREFIX/tmp}"
export HTTP_PROXY="http://127.0.0.1:$PORT" HTTPS_PROXY="http://127.0.0.1:$PORT"
export http_proxy="$HTTP_PROXY" https_proxy="$HTTPS_PROXY"
export NO_PROXY="localhost,127.0.0.1" no_proxy="localhost,127.0.0.1"
if [ -f "$PREFIX/etc/tls/cert.pem" ]; then
  export SSL_CERT_FILE="$PREFIX/etc/tls/cert.pem"
  export SSL_CERT_DIR="$PREFIX/etc/tls"
fi
command -v termux-open-url >/dev/null 2>&1 && export BROWSER="${BROWSER:-termux-open-url}"
# Bionic-oriented LD_* settings (termux-exec LD_PRELOAD etc.) poison glibc
# processes: the preload chain drags in bionic libc.so and kills the loader.
unset LD_PRELOAD LD_LIBRARY_PATH LD_AUDIT LD_DEBUG LD_BIND_NOW
# The CLI spawns git for repo scans with stdio on sockets it does not drain
# while waiting for git; outside a repository git replies with a multi-KB
# usage dump and deadlocks the UI. The shim answers those scans instantly.
SHIM_BIN="$DIR/shim-bin"
mkdir -p "$SHIM_BIN"
cp -f "$DIR/tools/git-shim" "$SHIM_BIN/git" 2>/dev/null || true
chmod 755 "$SHIM_BIN/git" 2>/dev/null || true
export PATH="$SHIM_BIN:$PATH"
export FREEBUFF_REAL_GIT="$(command -v git || echo $PREFIX/bin/git)"
# npm reports android/arm (or aarch64) on Termux; we run the matching release.
export CODEBUFF_BINARY_TARGET=@TARGET@
# Lets the official launcher re-patch updates before it respawns them.
export FREEBUFF_NATIVE_HOOK="$DIR/hooks.js"
# The terminal watchdog deadlocks TUI startup on Android; the launcher
# still resets the terminal on exit without it.
export CODEBUFF_NO_TERMINAL_WATCHDOG=1
# The launcher spawns the private loader directly (no interpreter rewrite
# needed, patchelf optional) and libraries resolve through the private set.
export FREEBUFF_LOADER_PATH="$DIR/lib/@LOADER@"
export FREEBUFF_LIB_DIR="$DIR/lib"

if ! (exec 3<>/dev/tcp/127.0.0.1/$PORT) 2>/dev/null; then
  nohup node "$DIR/proxy.mjs" >/dev/null 2>&1 &
  sleep 0.3
fi

repatch() {
  # No patchelf: the launcher spawns via the private loader (--library-path).
  if [ "@TARGET@" != "linux-x64" ]; then
    node "$DIR/patch-syscalls.mjs" "$1" >&2 || true
  fi
}
verify() {
  timeout 60 "$DIR/lib/@LOADER@" --library-path "$DIR/lib" "$1" --version >/dev/null 2>&1 \
    && timeout 60 "$DIR/lib/@LOADER@" --library-path "$DIR/lib" "$1" --help >/dev/null 2>&1
}
save_bak() {
  mkdir -p "$BAK" || return 0
  cp -f "$BIN" "$BAK/freebuff.bak" || true
  cp -f "$CONF/freebuff-metadata.json" "$BAK/" 2>/dev/null || true
  cp -f "$CONF/tree-sitter.wasm" "$BAK/" 2>/dev/null || true
}
restore_bak() {
  cp -f "$BAK/freebuff.bak" "$BIN"
  cp -f "$BAK/freebuff-metadata.json" "$CONF/" 2>/dev/null || true
  cp -f "$BAK/tree-sitter.wasm" "$CONF/" 2>/dev/null || true
}
recalc_md5() { md5sum "$BIN" 2>/dev/null | cut -d" " -f1 || echo none; }

# An npm reinstall of the package would wipe the launcher hook.
node "$DIR/fix-launcher.mjs" >/dev/null 2>&1 || true

# A failed or wiped update leaves no binary: restore before anything else.
if [ ! -f "$BIN" ] && [ -f "$BAK/freebuff.bak" ]; then
  echo "freebuff: binary missing; restoring last working copy" >&2
  restore_bak || true
fi

# Re-patch whenever the binary changed (the launcher installs on exit).
if [ -f "$BIN" ]; then
  SUM=$(recalc_md5)
  OLD=$(cat "$MD5F" 2>/dev/null || echo none)
  if [ "$SUM" != "$OLD" ]; then
    echo "freebuff: binary changed since last run; re-applying native patches..." >&2
    repatch "$BIN"
    if verify "$BIN"; then
      save_bak
      recalc_md5 > "$MD5F"
      echo "freebuff: $("$BIN" --version 2>/dev/null) ready (native, patched)" >&2
    elif [ -f "$BAK/freebuff.bak" ]; then
      echo "freebuff: new binary failed verification; restoring last working copy" >&2
      restore_bak
      recalc_md5 > "$MD5F"
    else
      echo "freebuff: WARNING: new binary failed verification and no backup exists" >&2
    fi
  fi
fi

if [ ! -f "$LAUNCHER" ]; then
  echo "freebuff: launcher missing: $LAUNCHER (npm package removed?)" >&2
  exit 1
fi
rc=0
node "$LAUNCHER" "$@" || rc=$?
# Self-heal: an update that landed mid-session made the spawned binary fail;
# re-patch and retry once.
if [ $rc -eq 126 ] || [ $rc -eq 127 ]; then
  echo "freebuff: launch failed with $rc; re-patching and retrying..." >&2
  repatch "$BIN"
  if verify "$BIN"; then
    save_bak; recalc_md5 > "$MD5F"
    exec node "$LAUNCHER" "$@"
  fi
  [ -f "$BAK/freebuff.bak" ] && { restore_bak; exec node "$LAUNCHER" "$@"; }
fi
exit $rc
